def subtract(a, b):
    # filter out empty/invalid intervals
    a = [iv for iv in a if iv[0] < iv[1]]
    b = [iv for iv in b if iv[0] < iv[1]]

    if not a:
        return []

    # gather all distinct points
    points = set()
    for s, e in a:
        points.add(s)
        points.add(e)
    for s, e in b:
        points.add(s)
        points.add(e)

    points = sorted(points)
    if not points:
        return []

    result = []
    current_start = None

    for i in range(len(points) - 1):
        seg_start = points[i]
        seg_end = points[i + 1]
        if seg_start >= seg_end:
            continue

        # check if this segment is covered by some interval in a
        in_a = any(s <= seg_start and seg_end <= e for s, e in a)
        # check if this segment is covered by some interval in b
        in_b = any(s <= seg_start and seg_end <= e for s, e in b)

        covered = in_a and not in_b

        if covered:
            if current_start is None:
                current_start = seg_start
            # continue building current segment, will be extended
        else:
            if current_start is not None:
                result.append([current_start, seg_start])
                current_start = None

    if current_start is not None:
        result.append([current_start, points[-1]])

    return result

